(()=>{let quiet=false;try{quiet=localStorage.getItem('correlated-reduced-motion')==='true'}catch{}quiet ||= matchMedia('(prefers-reduced-motion: reduce)').matches;function apply(){document.documentElement.classList.toggle('reduce-motion',quiet);document.querySelectorAll('.motion-toggle').forEach(b=>{b.textContent=`动态效果 ${quiet?'关':'开'}`;b.setAttribute('aria-pressed',String(quiet));});}document.querySelectorAll('.motion-toggle').forEach(b=>b.onclick=()=>{quiet=!quiet;try{localStorage.setItem('correlated-reduced-motion',quiet)}catch{}apply();});apply();})();
